"use client"

import { useEffect, useRef } from "react"

import ScrambleIn, {
  type ScrambleInHandle,
} from "@/registry/new-york/scramble-in"

export const ScrambleInPreview = () => {
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const el = containerRef.current
    if (!el) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          const children = el.querySelectorAll("[data-scramble]")
          children.forEach((child, i) => {
            setTimeout(() => {
              child.classList.add("scramble-active")
            }, i * 150)
          })
          observer.disconnect()
        }
      },
      { threshold: 0.3 }
    )

    observer.observe(el)
    return () => observer.disconnect()
  }, [])

  return (
    <div
      ref={containerRef}
      className="flex min-h-72 flex-col items-center justify-center gap-8 px-6 py-12"
    >
      <h1 className="text-4xl font-medium tracking-tight text-foreground sm:text-5xl md:text-6xl">
        <ScrambleIn
          text="Built for developers"
          scrambleSpeed={40}
          scrambledLetterCount={3}
          className="text-foreground"
        />
      </h1>
      <p className="max-w-md text-center text-lg text-muted-foreground leading-relaxed">
        <ScrambleIn
          text="Every animation resolves into clarity."
          scrambleSpeed={50}
          scrambledLetterCount={2}
          autoStart={false}
        />
      </p>
    </div>
  )
}

